fn numpy_greater_equal(x1: Vec<i8>, x2: Vec<i8>) -> Vec<bool> {
    // Initialize a boolean vector with the same length as the input vectors
    let mut result = Vec::with_capacity(x1.len());
    
    // Iterate through both vectors and compare elements
    for (a, b) in x1.iter().zip(x2.iter()) {
        result.push(a >= b); // Push true if a is greater than or equal to b
    }
    
    result // Return the resulting boolean vector
}